export default function CardBird({ className = "" }) {
  const root = useRef(null);
  const bird = useRef(null);
  const pupil = useRef(null);
  // un mask par instance : deux colibris sur la même page se voleraient l'id
  const maskId = `cb-eye-${useId().replace(/:/g, "")}`;

  useEffect(() => {
    const svg = root.current;
    const birdEl = bird.current;
    const pupilEl = pupil.current;
    if (!svg || !birdEl || !pupilEl) return undefined;

    const reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    if (reduced) return undefined;

    /*
      `quickTo` capture sa cible À LA CRÉATION : on lui passe donc les nœuds
      déjà montés, sinon GSAP journalise « target not found » et rien ne bouge.
      Il réutilise un seul tween, ce qui reste fluide à chaque frame.
    */
    const birdRot = gsap.quickTo(birdEl, "rotation", { duration: 0.8, ease: "power3.out" });
    const birdX = gsap.quickTo(birdEl, "x", { duration: 0.8, ease: "power3.out" });
    const birdY = gsap.quickTo(birdEl, "y", { duration: 0.8, ease: "power3.out" });
    // l'œil réagit plus vite que le corps : c'est ce décalage qui rend vivant
    const pupilX = gsap.quickTo(pupilEl, "x", { duration: 0.3, ease: "power3.out" });
    const pupilY = gsap.quickTo(pupilEl, "y", { duration: 0.3, ease: "power3.out" });

    const clamp = (v) => Math.max(-1, Math.min(1, v));

    const onMove = (e) => {
      const r = svg.getBoundingClientRect();
      if (!r.width) return;

      // distance normalisée : au-delà de ~520 px l'oiseau ne force plus
      const dx = clamp((e.clientX - (r.left + r.width / 2)) / 520);
      const dy = clamp((e.clientY - (r.top + r.height / 2)) / 520);

      birdRot(dx * 3);
      birdX(dx * 12);
      birdY(dy * 9);
      // amplitudes calées sur la géométrie : iris r≈10,1 / pupille r≈4,4,
      // donc 5,7 unités de débattement max — 4,2 × 3,3 garde une marge
      pupilX(dx * 4.2);
      pupilY(dy * 3.3);
    };

    window.addEventListener("mousemove", onMove);
    return () => window.removeEventListener("mousemove", onMove);
  }, []);

  return (
    <svg
      ref={root}
      viewBox={VIEW_BOX}
      className={className}
      role="img"
      aria-label="Colibri gravé dont le regard suit le curseur"
    >
      <defs>
        {/*
          Le mask est référencé par le path : il vit donc dans SON espace
          utilisateur et suit l'inclinaison du groupe parent. Le rect blanc
          couvre largement le viewBox, la pupille noire y perce le trou.
        */}
        <mask id={maskId} maskUnits="userSpaceOnUse" x="-200" y="-200" width="1000" height="1000">
          <rect x="-200" y="-200" width="1000" height="1000" fill="#fff" />
          <g ref={pupil}>
            <path d={PUPIL} fill="#000" />
          </g>
        </mask>
      </defs>

      {/* l'inclinaison pivote autour du corps, pas du centre du viewBox */}
      <g ref={bird} style={{ transformBox: "fill-box", transformOrigin: "57% 45%" }}>
        <path d={BIRD} fill="currentColor" mask={`url(#${maskId})`} />
      </g>
    </svg>
  );
}